      inner += at(1, 'pop', `<circle cx="${f(x)}" cy="${f(y)}" r="7" fill="${C.purple}" stroke="white" stroke-width="2"/>` + text(f(x + dx), f(y + dy), nm, { size: 18, anchor: dx < 0 ? 'end' : 'start' }), f(1.2 + i * 0.3));
