    let body = koreaMap(id, inner);
    css += `.sc-${id} .b1 .draw { stroke-dasharray: 1; }`;
    // 오른쪽 크게 본 김천: 빈 땅 → 기관 → 집·학교·가게 → 사람
    const IX = 380, IY = 100, IW = 244, IH = 224;
