    body += at(2, 'pop', text(IX + 70, IY + 58, '기관', { size: 18, color: C.purple }), 0.9);
    const homes = [[IX + 176, IY + 60], [IX + 214, IY + 60], [IX + 176, IY + 120], [IX + 214, IY + 120]];
    homes.forEach(([x, y], i) => { body += at(2, 'rise', house(x, y, 0.9), f(1.1 + i * 0.2)); });
    const school = `<rect x="${IX + 160}" y="${IY + 176}" width="66" height="36" fill="white" stroke="${C.orange}" stroke-width="2.5"/><path d="M${IX + 154} ${IY + 178} L${IX + 193} ${IY + 160} L${IX + 232} ${IY + 178}" fill="${C.peach}" stroke="${C.orange}" stroke-width="2.5" stroke-linejoin="round"/>`;
